/**
 * Loads the bundled dataset snapshot (public/data, generated by
 * scripts/build_dataset.py from Zenodo record 22042887). Cached per session.
 */
import type { Comment, DatasetMeta, Emotion, SocialPost } from "@/types";
import { apiGet, isApiMode, staticGet } from "./api/client";
import { ENDPOINTS } from "./api/config";

let postsPromise: Promise<SocialPost[]> | null = null;
let commentsPromise: Promise<Comment[]> | null = null;
let metaPromise: Promise<DatasetMeta> | null = null;

export function loadPosts(): Promise<SocialPost[]> {
  postsPromise ??= staticGet<SocialPost[]>("/data/posts.json").catch((e) => {
    postsPromise = null;
    throw e;
  });
  return postsPromise;
}

export function loadComments(): Promise<Comment[]> {
  commentsPromise ??= staticGet<[string, string, string, Emotion][]>("/data/comments.json")
    .then((rows) => rows.map(([id, ts, parentId, emotion]) => ({ id, ts, parentId, emotion })))
    .catch((e) => {
      commentsPromise = null;
      throw e;
    });
  return commentsPromise;
}

export function loadMeta(): Promise<DatasetMeta> {
  metaPromise ??= staticGet<DatasetMeta>("/data/meta.json").catch((e) => {
    metaPromise = null;
    throw e;
  });
  return metaPromise;
}

export const datasetService = {
  async getMeta(signal?: AbortSignal): Promise<DatasetMeta> {
    if (isApiMode()) return apiGet<DatasetMeta>(ENDPOINTS.meta, undefined, signal);
    return loadMeta();
  },
  async getRawPosts(signal?: AbortSignal): Promise<SocialPost[]> {
    if (isApiMode()) return apiGet<SocialPost[]>(ENDPOINTS.posts, { all: true }, signal);
    return loadPosts();
  },
  async getRawComments(signal?: AbortSignal): Promise<Comment[]> {
    if (isApiMode()) return apiGet<Comment[]>(ENDPOINTS.comments, { all: true }, signal);
    return loadComments();
  },
  async health(signal?: AbortSignal): Promise<{ ok: boolean }> {
    return apiGet<{ ok: boolean }>(ENDPOINTS.health, undefined, signal);
  },
};
